319	    try {
320	      if (!formProduto.trim() || !formNcm.trim()) {
321	        toast({ title: "Campos obrigatórios", description: "Preencha produto e NCM." });
322	        return;
323	      }
324	      const payload = {
325	        produto_nome: formProduto.trim(),
326	        ncm: formNcm.trim(),
327	        categoria: formCategoria,
328	        descricao: formDescricao.trim() || null,
329	        custo: parseCurrency(formCusto),
330	      };
331	
332	      if (editingItem) {
333	        const { error } = await supabase
334	          .from("ncm_produtos")
335	          .update(payload)
336	          .eq("produto_nome", editingItem.produto_nome);
337	        if (error) throw error;
338	        toast({ title: "Atualizado", description: "Registro atualizado com sucesso" });
339	      } else {
