378	        const rows: ImportRow[] = XLSX.utils.sheet_to_json(sheet, { defval: "" }) as ImportRow[];
379	
380	        const toUpsert = rows
381	          .map((r) => {
382	            const nome = String(r.produto ?? r.produto_nome ?? r.nome ?? "").trim();
383	            const ncm = String(r.ncm ?? "").trim();
384	            const categoriaRaw = String(r.categoria ?? r.tipo ?? "").trim();
385	            const cat = normalizeCategoria(categoriaRaw);
386	            const descricao = String(r.descricao ?? "").trim();
387	            if (!nome || !ncm || !cat) return null;
388	            return {
389	              produto_nome: nome,
390	              ncm,
391	              categoria: cat,
392	              descricao: descricao || null,
393	            } as const;
394	          })
