416	      };
417	      reader.readAsArrayBuffer(file);
418	      // Reset input to allow same file re-upload
419	      e.target.value = "";
420	    } catch (error) {
421	      console.error("Erro ao importar arquivo:", error);
422	      toast({ title: "Erro na importação", description: "Verifique o arquivo e tente novamente" });
423	    }
424	  };
