import { Label } from "@/shared/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { toast } from "@/shared/ui/use-toast";
import { supabase } from "@/integrations/supabase/client";
import * as XLSX from "xlsx";
import { PermissionBlur } from "@/shared/ui/PermissionBlur";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { useMiaNCMActions } from "@/features/mia/model/hooks";

type Categoria =
  | "insumos"
  | "embalagens"
  | "descartaveis"
  | "bebidas"
  | "mercearia"
  | "material_limpeza"
  | "insumos_momma_brunch"
  | "finalizados";

type NcmProduto = {
  id: number;
  produto_nome: string;
  ncm: string;
  categoria: Categoria;
  descricao: string | null;
  custo: number | null;
  loja_id: number | null;
  created_at: string | null;
  updated_at: string | null;
};

const categoriaLabels: Record<Categoria, string> = {
  insumos: "Insumos",
  embalagens: "Embalagens",
  descartaveis: "Descartáveis",
  bebidas: "Bebidas",
  mercearia: "Mercearia",
  material_limpeza: "Material de Limpeza",
  insumos_momma_brunch: "Insumos Momma Brunch",
  finalizados: "Produtos Finalizados",
};

function normalizeCategoria(value: string): Categoria | null {
  const v = value.trim().toLowerCase();
  if (["insumo", "insumos"].includes(v)) return "insumos";
  if (["insumos momma brunch", "insumos momma"].includes(v)) return "insumos_momma_brunch";
  if (["embalagem", "embalagens"].includes(v)) return "embalagens";
  if (["descartavel", "descartáveis", "descartaveis"].includes(v)) return "descartaveis";
  if (["bebida", "bebidas"].includes(v)) return "bebidas";
  if (["mercearia"].includes(v)) return "mercearia";
  if (["material de limpeza", "limpeza"].includes(v)) return "material_limpeza";
  if (["finalizado", "finalizados", "produto finalizado", "produtos finalizados"].includes(v)) return "finalizados";
  return null;
}

interface ConsultarNcmsProps {
  onBack?: () => void;
}

export function ConsultarNcms({ onBack }: ConsultarNcmsProps) {
  const [items, setItems] = useState<NcmProduto[]>([]);
  const [loading, setLoading] = useState(false);
  const [categoriaFilter, setCategoriaFilter] = useState<Categoria | "all">("all");
  const [ncmFilter, setNcmFilter] = useState<"all" | "com" | "sem">("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<NcmProduto | null>(null);

  const [formProduto, setFormProduto] = useState("");
  const [formNcm, setFormNcm] = useState("");
  const [formCategoria, setFormCategoria] = useState<Categoria>("insumos");
  const [formDescricao, setFormDescricao] = useState("");
  const [formCusto, setFormCusto] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { canViewNCM } = usePermissions();
  const hasAccess = canViewNCM();

  useMiaNCMActions({
    setCategoriaFilter: (v: string) => setCategoriaFilter(v as Categoria | "all"),
    setSearchTerm,
  });

  useEffect(() => {
    fetchItems();
  }, []);

  const fetchItems = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("ncm_produtos")
        .select("*")
        .order("produto_nome", { ascending: true });
      if (error) throw error;
      const arr = (data || []) as NcmProduto[];
      const dedup = new Map<string, NcmProduto>();
      for (const it of arr) {
        const existing = dedup.get(it.produto_nome);
        if (!existing || (!existing.ncm && it.ncm)) {
          dedup.set(it.produto_nome, it);
        }
      }
      setItems(Array.from(dedup.values()));
    } catch (error) {
      console.error("Erro ao buscar NCMs:", error);
      toast({ title: "Erro ao carregar", description: "Não foi possível carregar os NCMs" });
    } finally {
      setLoading(false);
    }
  };

  const filteredItems = useMemo(() => {
    const filtered = items
      .filter((it) => categoriaFilter === "all" || it.categoria === categoriaFilter)
      .filter((it) => (ncmFilter === "all" ? true : ncmFilter === "com" ? Boolean(it.ncm) : !it.ncm))
      .filter((it) =>
        searchTerm ? it.produto_nome.toLowerCase().includes(searchTerm.toLowerCase()) || (it.ncm || "").includes(searchTerm) : true
      );

    const dedup = new Map<string, NcmProduto>();
    for (const it of filtered) {
      const prev = dedup.get(it.produto_nome);
      if (!prev || (!prev.ncm && it.ncm)) dedup.set(it.produto_nome, it);
    }
    return Array.from(dedup.values());
  }, [items, categoriaFilter, ncmFilter, searchTerm]);

  const groupedForPrint = useMemo(() => {
    const ordered: Categoria[] = [
      "insumos",
      "embalagens",
      "descartaveis",
      "bebidas",
      "mercearia",
      "material_limpeza",
      "insumos_momma_brunch",
      "finalizados",
    ];
    const map = new Map<Categoria, NcmProduto[]>();
    for (const it of filteredItems) {
      const arr = map.get(it.categoria) || [];
      arr.push(it);
      map.set(it.categoria, arr);
    }
    const groups: [Categoria, NcmProduto[]][] = [];
    for (const cat of ordered) {
      const arr = map.get(cat);
      if (arr && arr.length) groups.push([cat, arr.sort((a, b) => a.produto_nome.localeCompare(b.produto_nome))]);
    }
    return groups;
  }, [filteredItems]);

  // groupedForPrint is used in handlePrint below
  void groupedForPrint;

  const handlePrint = () => {
    try {
      const ordered: Categoria[] = [
        'insumos',
        'embalagens',
        'descartaveis',
        'bebidas',
        'mercearia',
        'material_limpeza',
        'insumos_momma_brunch',
        'finalizados',
      ];

      const map = new Map<Categoria, NcmProduto[]>();
      for (const it of filteredItems) {
        const arr = map.get(it.categoria) || [];
        arr.push(it);
        map.set(it.categoria, arr);
      }

      const groups = ordered
        .map((cat) => {
          const arr = map.get(cat);
          if (!arr || arr.length === 0) return null;
          return [cat, arr.sort((a, b) => a.produto_nome.localeCompare(b.produto_nome))] as [Categoria, NcmProduto[]];
        })
        .filter((x): x is [Categoria, NcmProduto[]] => Boolean(x));

      const isSingle = groups.length === 1;

      const pages: [Categoria, NcmProduto[]][][] = [];
      if (isSingle) {
        pages.push(groups);
      } else {
        for (let i = 0; i < groups.length; i += 2) {
          pages.push(groups.slice(i, i + 2));
        }
      }

      const pagesHtml = pages
        .map((page) => {
          const colsClass = isSingle ? 'grid-1' : 'grid-2';
          const catsHtml = page
            .map(([cat, arr]) => {
              const rows = arr
                .map(
                  (item) => `
                  <tr>
                    <td class="cell name">${item.produto_nome}</td>
                    <td class="cell ncm">${formatNcm(item.ncm || '')}</td>
                    <td class="cell valor">${formatCurrency(item.custo)}</td>
                  </tr>
                `
                )
                .join('');
              return `
                <div class="category">
                  <div class="category-title">${categoriaLabels[cat].toUpperCase()}</div>
                  <table class="table">
                    <thead>
                      <tr>
                        <th class="head">Produto</th>
                        <th class="head">NCM</th>
                        <th class="head">Valor</th>
                      </tr>
                    </thead>
                    <tbody>${rows}</tbody>
                  </table>
                </div>
              `;
            })
            .join('');
          return `
            <div class="page">
              <div class="${colsClass}">${catsHtml}</div>
            </div>
          `;
        })
        .join('');

      const html = `<!DOCTYPE html>
      <html>
      <head>
        <title>Lista de NCMs</title>
        <style>
          @page { margin: 12mm; size: A4; }
          * { margin: 0; padding: 0; box-sizing: border-box; }
          body { font-family: Arial, sans-serif; font-size: 11px; line-height: 1.25; }
          .header { background-color: #4CAF50; color: white; text-align: center; padding: 8px; font-weight: bold; font-size: 14px; }
          .header-title { letter-spacing: 0.5px; }
          .grid-1 { display: grid; grid-template-columns: 1fr; gap: 8px; margin-top: 10px; }
          .grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-top: 10px; }
          .category { border: 1px solid #333; }
          .category-title { padding: 6px 8px; background-color: #2E7D32; color: white; font-weight: bold; letter-spacing: 0.5px; }
          .table { width: 100%; border-collapse: collapse; }
          .head { background-color: #f0f0f0; border: 1px solid #333; padding: 4px; text-align: left; font-size: 10px; }
          .cell { border: 1px solid #333; padding: 3px 6px; font-size: 10px; }
          .name { font-weight: bold; }
          .ncm { text-align: left; }
          .valor { text-align: left; }
          .page { page-break-after: always; break-after: page; }
          .page:last-child { page-break-after: auto; break-after: auto; }
          @media print { body { -webkit-print-color-adjust: exact; } }
        </style>
      </head>
      <body>
        <div class="header"><span class="header-title">MOMMA DOCES SAUDÁVEIS</span></div>
        ${pagesHtml}
      </body>
      </html>`;

      printHTML(html, { title: 'NCMs - Momma' });
    } catch (e) { console.error(e); }
  };

  const formatNcm = (n: string | null) => {
    if (!n) return "";
    const s = String(n).replace(/[^0-9]/g, "");
    if (s.length === 8) return `${s.slice(0,4)}.${s.slice(4,6)}.${s.slice(6,8)}`;
    return n;
  };

  const formatCurrency = (v: number | null) => {
    if (v == null) return "";
    try {
      return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    } catch {
      return String(v);
    }
  };

  const parseCurrency = (s: string) => {
    const t = s.trim();
    if (!t) return null;
    const v = t.replace(/[^0-9,.-]/g, "").replace(/\./g, "").replace(/,/g, ".");
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  const openCreate = () => {
    setEditingItem(null);
    setFormProduto("");
    setFormNcm("");
    setFormCategoria("insumos");
    setFormDescricao("");
    setFormCusto("");
    setIsModalOpen(true);
  };

  const openEdit = (item: NcmProduto) => {
    setEditingItem(item);
    setFormProduto(item.produto_nome);
    setFormNcm(item.ncm);
    setFormCategoria(item.categoria);
    setFormDescricao(item.descricao || "");
    setFormCusto(item.custo != null ? String(item.custo) : "");
    setIsModalOpen(true);
  };

  const handleSave = async () => {
    try {
      if (!formProduto.trim() || !formNcm.trim()) {
        toast({ title: "Campos obrigatórios", description: "Preencha produto e NCM." });
        return;
      }
      const payload = {
        produto_nome: formProduto.trim(),
        ncm: formNcm.trim(),
        categoria: formCategoria,
        descricao: formDescricao.trim() || null,
        custo: parseCurrency(formCusto),
      };

      if (editingItem) {
        const { error } = await supabase
          .from("ncm_produtos")
          .update(payload)
          .eq("produto_nome", editingItem.produto_nome);
        if (error) throw error;
        toast({ title: "Atualizado", description: "Registro atualizado com sucesso" });
      } else {
        const { error } = await supabase.from("ncm_produtos").insert(payload);
        if (error) throw error;
        toast({ title: "Adicionado", description: "Registro criado com sucesso" });
      }
      setIsModalOpen(false);
      fetchItems();
    } catch (error) {
      console.error("Erro ao salvar NCM:", error);
      toast({ title: "Erro", description: "Não foi possível salvar o registro" });
    }
  };

  const handleDelete = async (item: NcmProduto) => {
    try {
      const { error } = await supabase.from("ncm_produtos").delete().eq("produto_nome", item.produto_nome);
      if (error) throw error;
      toast({ title: "Removido", description: "Registro excluído" });
      fetchItems();
    } catch (error) {
      console.error("Erro ao excluir NCM:", error);
      toast({ title: "Erro", description: "Não foi possível excluir" });
    }
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange: React.ChangeEventHandler<HTMLInputElement> = async (e) => {
    try {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
        const data = new Uint8Array(ev.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: "array" });
        const sheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        const rows: ImportRow[] = XLSX.utils.sheet_to_json(sheet, { defval: "" }) as ImportRow[];

        const toUpsert = rows
          .map((r) => {
            const nome = String(r.produto ?? r.produto_nome ?? r.nome ?? "").trim();
            const ncm = String(r.ncm ?? "").trim();
            const categoriaRaw = String(r.categoria ?? r.tipo ?? "").trim();
            const cat = normalizeCategoria(categoriaRaw);
            const descricao = String(r.descricao ?? "").trim();
            if (!nome || !ncm || !cat) return null;
            return {
              produto_nome: nome,
              ncm,
              categoria: cat,
              descricao: descricao || null,
            } as const;
          })
          .filter(Boolean) as Array<{ produto_nome: string; ncm: string; categoria: Categoria; descricao: string | null }>;

        if (toUpsert.length === 0) {
          toast({ title: "Arquivo vazio", description: "Não há registros válidos para importar" });
          return;
        }

        const { error } = await supabase
          .from("ncm_produtos")
          .upsert(toUpsert.map(r => ({ ...r, loja_id: null })), { onConflict: "produto_nome,loja_id" });
        if (error) throw error;

        // Atualizar registros existentes (todas lojas) para refletir dados importados
        for (const r of toUpsert) {
          await supabase
            .from("ncm_produtos")
            .update({ ncm: r.ncm, categoria: r.categoria, descricao: r.descricao })
            .eq("produto_nome", r.produto_nome);
        }
        toast({ title: "Importado", description: `${toUpsert.length} registros importados/atualizados` });
        fetchItems();
      };
      reader.readAsArrayBuffer(file);
      // Reset input to allow same file re-upload
      e.target.value = "";
    } catch (error) {
      console.error("Erro ao importar arquivo:", error);
      toast({ title: "Erro na importação", description: "Verifique o arquivo e tente novamente" });
    }
  };

  return (
    <PermissionBlur hasPermission={hasAccess} moduleName="Financeiro" permissionName="view_ncm">
    <div className="min-h-screen max-w-full overflow-x-hidden px-3 sm:px-4 md:px-6 space-y-6 pb-24 print:hidden">
      {onBack && (
        <Button variant="ghost" onClick={onBack} className="gap-2 -ml-2 text-[#57715B] hover:bg-[#57715B]/10">
          <ArrowLeft className="h-4 w-4" />
          Voltar
        </Button>
      )}
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-3">
        <div className="text-center sm:text-left">
          <h1 className="text-2xl font-semibold tracking-tight text-foreground">Consultar NCMs</h1>
          <p className="text-sm text-muted-foreground">Produtos e seus respectivos códigos NCM</p>
        </div>
        <div className="flex flex-wrap gap-2 sm:gap-3 w-full sm:w-auto items-center">
          <Button data-mia-action="open-create" variant="outline" onClick={openCreate} className="gap-2">
            <Plus className="h-4 w-4" />
            Novo registro
          </Button>
          <Button data-mia-action="import-click" variant="outline" onClick={handleImportClick} className="gap-2">
            <Upload className="h-4 w-4" />
            Importar CSV/XLSX
          </Button>
          <Button data-mia-action="print" variant="outline" onClick={handlePrint} className="gap-2">
            <Printer className="h-4 w-4" />
            Imprimir
          </Button>
          <input ref={fileInputRef} type="file" accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" className="hidden" onChange={handleFileChange} />
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            <FileText className="h-5 w-5" /> Lista de NCMs
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-4">
            <div>
              <Label className="text-xs">Filtrar por categoria</Label>
              <Select value={categoriaFilter} onValueChange={(v) => setCategoriaFilter(v as Categoria | "all")}>
                <SelectTrigger className="h-8">
                  <SelectValue placeholder="Todas" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todas</SelectItem>
                  <SelectItem value="insumos">Insumos</SelectItem>
                  <SelectItem value="embalagens">Embalagens</SelectItem>
                  <SelectItem value="descartaveis">Descartáveis</SelectItem>
                  <SelectItem value="bebidas">Bebidas</SelectItem>
                  <SelectItem value="mercearia">Mercearia</SelectItem>
                  <SelectItem value="material_limpeza">Material de Limpeza</SelectItem>
                  <SelectItem value="insumos_momma_brunch">Insumos Momma Brunch</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs">Filtrar por NCM</Label>
              <Select value={ncmFilter} onValueChange={(v) => setNcmFilter(v as "all" | "com" | "sem")}>
                <SelectTrigger className="h-8">
                  <SelectValue placeholder="Todos" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="com">Com NCM</SelectItem>
                  <SelectItem value="sem">Sem NCM</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="md:col-span-2">
              <Label className="text-xs">Busca</Label>
              <div className="flex gap-2">
                <Input data-mia-field="search_term" placeholder="Produto ou NCM" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                <Button variant="outline" className="gap-2">
                  <Search className="h-4 w-4" />
                  Buscar
                </Button>
              </div>
            </div>
          </div>

          {loading ? (
            <div className="h-40 flex items-center justify-center text-muted-foreground">Carregando...</div>
          ) : filteredItems.length === 0 ? (
            <div className="h-40 flex items-center justify-center text-muted-foreground">Nenhum registro encontrado</div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
          <TableHeader>
            <TableRow>
              <TableHead>#</TableHead>
              <TableHead>Produto</TableHead>
              <TableHead>NCM</TableHead>
              <TableHead>Custo</TableHead>
              <TableHead>Categoria</TableHead>
              <TableHead className="text-right">Ações</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredItems.map((item, idx) => (
              <TableRow key={item.produto_nome}>
                <TableCell className="w-10 text-muted-foreground">{idx + 1}</TableCell>
                <TableCell className="font-medium">{item.produto_nome}</TableCell>
                <TableCell>{item.ncm}</TableCell>
                <TableCell>{formatCurrency(item.custo)}</TableCell>
                <TableCell>{categoriaLabels[item.categoria]}</TableCell>
                <TableCell className="text-right">
                  <div className="flex justify-end gap-2">
                    <Button variant="outline" size="sm" className="h-8" onClick={() => openEdit(item)}>
                      <Pencil className="h-4 w-4" />
                    </Button>
                    <Button variant="destructive" size="sm" className="h-8" onClick={() => handleDelete(item)}>
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
              </Table>
            </div>
          )}
      </CardContent>
      </Card>

      <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingItem ? "Editar NCM" : "Novo NCM"}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <Label>Produto</Label>
              <Input data-mia-field="form_produto" value={formProduto} onChange={(e) => setFormProduto(e.target.value)} placeholder="Nome do produto" />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <div>
                <Label>NCM</Label>
                <Input data-mia-field="form_ncm" value={formNcm} onChange={(e) => setFormNcm(e.target.value)} placeholder="Ex: 1905.90.10" />
              </div>
              <div>
                <Label>Categoria</Label>
                <Select value={formCategoria} onValueChange={(v) => setFormCategoria(v as Categoria)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="insumos">Insumos</SelectItem>
                    <SelectItem value="embalagens">Embalagens</SelectItem>
                    <SelectItem value="descartaveis">Descartáveis</SelectItem>
                    <SelectItem value="bebidas">Bebidas</SelectItem>
                    <SelectItem value="mercearia">Mercearia</SelectItem>
                    <SelectItem value="material_limpeza">Material de Limpeza</SelectItem>
                    <SelectItem value="insumos_momma_brunch">Insumos Momma Brunch</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Custo</Label>
                <Input data-mia-field="form_custo" value={formCusto} onChange={(e) => setFormCusto(e.target.value)} placeholder="Ex: 12,34" />
              </div>
            </div>
            <div>
              <Label>Descrição (opcional)</Label>
              <Input data-mia-field="form_descricao" value={formDescricao} onChange={(e) => setFormDescricao(e.target.value)} placeholder="Observações" />
            </div>
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
              <Button data-mia-action="save" onClick={handleSave}>Salvar</Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
    </PermissionBlur>
  );
}

// default export for backwards compatibility
export default ConsultarNcms;

type ImportRow = {
  produto?: unknown;
  produto_nome?: unknown;
  nome?: unknown;
  ncm?: unknown;
  categoria?: unknown;
  tipo?: unknown;
  descricao?: unknown;
};

